import{_ as t,o,c as a,ae as i}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"omm Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),d={name:"guide/architecture.md"};function s(n,e,r,l,c,m){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="omm-architecture-overview" tabindex="-1">omm Architecture Overview <a class="header-anchor" href="#omm-architecture-overview" aria-label="Permalink to &quot;omm Architecture Overview&quot;">​</a></h1><blockquote><p>oh-my-matrix (omm) v0.2.0 — OpenClaw-native orchestration extension suite</p></blockquote><h2 id="project-positioning" tabindex="-1">Project Positioning <a class="header-anchor" href="#project-positioning" aria-label="Permalink to &quot;Project Positioning&quot;">​</a></h2><p>omm provides persistent workflow capabilities (ralph/autopilot/team) for any OpenClaw-compatible host. It is modeled after <a href="https://github.com/anthropics/oh-my-codex" target="_blank" rel="noreferrer">oh-my-codex</a> but redesigned as a <strong>pure plugin</strong> — no standalone CLI, no Rust native modules, zero runtime dependencies.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>oh-my-codex</th><th>omm</th></tr></thead><tbody><tr><td>Runtime</td><td>Standalone CLI (<code>omx</code>)</td><td>OpenClaw plugin loaded by Gateway</td></tr><tr><td>Team parallelism</td><td>Self-built tmux + git worktree</td><td>Delegates to host team skill</td></tr><tr><td>MCP implementation</td><td><code>@modelcontextprotocol/sdk</code></td><td>Hand-written JSON-RPC (zero-dependency)</td></tr><tr><td>Distribution</td><td>npm binary + 4 Rust crates</td><td>Single tarball, JS-only</td></tr></tbody></table><p>See <a href="/reference/adrs/001.html">ADR-001</a>, <a href="/reference/adrs/002.html">ADR-002</a>, <a href="/reference/adrs/003.html">ADR-003</a> for rationale.</p><h2 id="module-decomposition" tabindex="-1">Module Decomposition <a class="header-anchor" href="#module-decomposition" aria-label="Permalink to &quot;Module Decomposition&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omm-packages/</span></span>
<span class="line"><span>├── omm-plugin/     OpenClaw plugin — tools, hooks, state validation</span></span>
<span class="line"><span>├── omm-mcp/        Stdio JSON-RPC MCP server for out-of-process state access</span></span>
<span class="line"><span>└── omm-skills/     SKILL.md definitions for workflow modes</span></span></code></pre></div><h3 id="omm-plugin" tabindex="-1">omm-plugin <a class="header-anchor" href="#omm-plugin" aria-label="Permalink to &quot;omm-plugin&quot;">​</a></h3><p>The plugin entry point <code>register(api)</code> conforms to the OpenClaw Plugin ABI:</p><ul><li><strong>5 tools</strong> registered via <code>api.registerTool()</code>: <code>omm_ping</code>, <code>omm_cancel</code>, <code>omm_state_write</code>, <code>omm_state_read</code>, <code>omm_state_list</code></li><li><strong>2 lifecycle hooks</strong> registered via <code>api.on()</code>: <code>session_start</code>, <code>session_end</code></li><li>All tools are <code>{ optional: true }</code> — the host functions without omm</li></ul><p>Key modules:</p><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>omm-register.ts</code></td><td>Plugin entry point; wires tools and hooks to the OpenClaw API</td></tr><tr><td><code>omm-state-validation.ts</code></td><td>Mode-aware state validation for ralph/autopilot/team</td></tr><tr><td><code>omm-config.ts</code></td><td>Resolves state root directory; defaults to <code>~/.openclaw/omm</code></td></tr><tr><td><code>omm-state.ts</code></td><td>Smoke record writer for session lifecycle events</td></tr><tr><td><code>omm-tools/omm-state.ts</code></td><td>State read/write/list tools with atomic persistence</td></tr><tr><td><code>omm-tools/omm-ping.ts</code></td><td>Health-check tool</td></tr><tr><td><code>omm-tools/omm-cancel.ts</code></td><td>Session cancellation tool</td></tr></tbody></table><h3 id="omm-mcp" tabindex="-1">omm-mcp <a class="header-anchor" href="#omm-mcp" aria-label="Permalink to &quot;omm-mcp&quot;">​</a></h3><p>A standalone stdio JSON-RPC server implementing MCP protocol 2024-11-05. Exposes the same three state tools (<code>read</code>, <code>write</code>, <code>list</code>) over stdio transport, enabling out-of-process access from any MCP client.</p><p>Inlines a simplified copy of the validation logic from <code>omm-state-validation.ts</code> to maintain zero cross-package dependencies.</p><p>See <a href="/reference/adrs/003.html">ADR-003</a> and <a href="/reference/contracts/mcp-protocol.html">MCP Protocol Contract</a>.</p><h3 id="omm-skills" tabindex="-1">omm-skills <a class="header-anchor" href="#omm-skills" aria-label="Permalink to &quot;omm-skills&quot;">​</a></h3><p>Five SKILL.md files define workflow behaviors:</p><table tabindex="0"><thead><tr><th>Skill</th><th>Type</th><th>State Machine</th></tr></thead><tbody><tr><td><code>omm-ping</code></td><td>Tool dispatch</td><td>Direct <code>omm_ping</code> call</td></tr><tr><td><code>omm-cancel</code></td><td>Tool dispatch</td><td>Direct <code>omm_cancel</code> call</td></tr><tr><td><code>omm-ralph</code></td><td>Model-driven</td><td>INIT → PLANNING → EXECUTING → VERIFYING ↔ FIXING → COMPLETE/FAILED</td></tr><tr><td><code>omm-autopilot</code></td><td>Model-driven</td><td>ANALYZING → PLANNING → STEP_N → VERIFYING ↔ RETRY → COMPLETE/BLOCKED/FAILED</td></tr><tr><td><code>omm-team</code></td><td>Model-driven</td><td>PLANNING → DECOMPOSING → DELEGATING → EXECUTING → VERIFYING ↔ FIXING → COMPLETE/FAILED</td></tr></tbody></table><p>See <a href="/reference/adrs/004.html">ADR-004</a> and <a href="/reference/contracts/workflow-state.html">Workflow State Contract</a>.</p><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><h3 id="state-write-path" tabindex="-1">State Write Path <a class="header-anchor" href="#state-write-path" aria-label="Permalink to &quot;State Write Path&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tool call (omm_state_write)</span></span>
<span class="line"><span>  → Input validation (key required, value is object)</span></span>
<span class="line"><span>  → Mode-aware validation (validateStateWrite)</span></span>
<span class="line"><span>    → Route by mode: value.mode ?? key</span></span>
<span class="line"><span>    → Known modes: enforce phase set, counter invariants, terminal rules</span></span>
<span class="line"><span>    → Unknown keys: pass through with timestamp</span></span>
<span class="line"><span>  → Atomic persistence (writeFile tmp → rename)</span></span>
<span class="line"><span>  → Response to caller</span></span></code></pre></div><h3 id="dual-access-model" tabindex="-1">Dual-Access Model <a class="header-anchor" href="#dual-access-model" aria-label="Permalink to &quot;Dual-Access Model&quot;">​</a></h3><p>The same state directory (<code>{stateRoot}/state/</code>) is accessible via two paths:</p><ol><li><strong>In-process</strong>: OpenClaw plugin tools — used during normal skill execution</li><li><strong>Out-of-process</strong>: MCP server over stdio — used by external MCP clients</li></ol><p>Both paths apply validation before writing. The MCP server inlines equivalent validation logic.</p><p>See <a href="/reference/contracts/state-contract.html">State Contract</a>.</p><h2 id="host-boundary" tabindex="-1">Host Boundary <a class="header-anchor" href="#host-boundary" aria-label="Permalink to &quot;Host Boundary&quot;">​</a></h2><h3 id="what-omm-owns" tabindex="-1">What omm owns <a class="header-anchor" href="#what-omm-owns" aria-label="Permalink to &quot;What omm owns&quot;">​</a></h3><ul><li>State persistence and validation</li><li>Workflow skill definitions (SKILL.md lifecycle instructions)</li><li>Build and compliance toolchain</li></ul><h3 id="what-the-host-provides" tabindex="-1">What the host provides <a class="header-anchor" href="#what-the-host-provides" aria-label="Permalink to &quot;What the host provides&quot;">​</a></h3><ul><li><strong>OpenClaw Gateway</strong>: Plugin loading, tool dispatch, skill execution engine</li><li><strong>Team parallelism</strong>: <code>TeamCreate</code>/<code>TaskCreate</code>/<code>SendMessage</code> for parallel workers</li><li><strong>Skill runtime</strong>: Model invocation, SKILL.md interpretation, frontmatter processing</li><li><strong>Consumer integration</strong>: Tarball unpacking, config injection at startup</li></ul><h3 id="consumer-integration" tabindex="-1">Consumer Integration <a class="header-anchor" href="#consumer-integration" aria-label="Permalink to &quot;Consumer Integration&quot;">​</a></h3><p>The primary consumer (MatrixAssistant) integrates omm via:</p><ol><li><code>omm-build-suite.mjs</code> produces <code>omm-suite-&lt;version&gt;.tgz</code> with SHA-256 manifest</li><li><code>scripts/omm-bundle.mjs</code> unpacks and verifies the tarball into <code>resources/</code></li><li><code>electron/utils/omm-openclaw-seed.ts</code> injects omm config into <code>openclaw.json</code> at startup</li><li>OpenClaw Gateway discovers the plugin and skills automatically</li></ol><h2 id="extension-points" tabindex="-1">Extension Points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension Points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Extension</th><th>How</th></tr></thead><tbody><tr><td>Add a new tool</td><td>Create handler in <code>omm-tools/</code>, register in <code>omm-register.ts</code>, add to consumer whitelist</td></tr><tr><td>Add a new skill</td><td>Create <code>omm-skills/&lt;name&gt;/SKILL.md</code>, bundle includes it automatically</td></tr><tr><td>Add a new state mode</td><td>Add validator function in <code>omm-state-validation.ts</code>, add to <code>VALIDATORS</code> map</td></tr><tr><td>Add a lifecycle hook</td><td>Register via <code>api.on()</code> in <code>omm-register.ts</code></td></tr></tbody></table><h2 id="build-and-compliance" tabindex="-1">Build and Compliance <a class="header-anchor" href="#build-and-compliance" aria-label="Permalink to &quot;Build and Compliance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th></tr></thead><tbody><tr><td><code>omm-build-suite.mjs</code></td><td>Stage + tarball with SHA-256 manifest</td></tr><tr><td><code>omm-scan-names.mjs</code></td><td>Hash-based forbidden name denylist scan</td></tr><tr><td><code>omm-verify-bundle.mjs</code></td><td>Tarball integrity verification against manifest</td></tr><tr><td><code>omm-verify-provenance.mjs</code></td><td>Provenance metadata validation</td></tr></tbody></table><p>CI pipeline (<code>.gitlab-ci.yml</code>): install → build → test → lint → scan-names → verify-provenance → verify-bundle</p><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Framework: <code>node:test</code> (zero dependencies)</li><li>Co-located test files: <code>*.test.ts</code> alongside source</li><li>25 test cases covering: state validation (17), state tools (8), ping, cancel</li><li>Tests run against compiled JS: <code>node --test omm-packages/omm-plugin/dist/src/**/*.test.js</code></li></ul>`,44)])])}const u=t(d,[["render",s]]);export{h as __pageData,u as default};
